pub fn solve(input: Vec<char>) -> Vec<char> {
    // Helper to map a digit character to its good count.
    fn good_count(d: char) -> usize {
        match d {
            '0' | '2' | '6' | '9' => 2,
            '1' => 7,
            '3' | '4' => 3,
            '5' => 4,
            '7' => 5,
            '8' => 1,
            _ => 0, // Shouldn't happen given the problem constraints
        }
    }

    // We only care about the first two characters of the input.
    let a = good_count(input[0]);
    let b = good_count(input[1]);
    let product = a * b;

    // Convert the product to its decimal representation as chars, then append a newline.
    let mut output: Vec<char> = product.to_string().chars().collect();
    output.push('\n');
    output
}